def _eval_subs(self, old, new):
    from sympy import exp, log, Symbol

    def _check(ct1, ct2, old):
        """Return (bool, pow, remainder_pow) where, if bool is True, then the
        exponent of Pow `old` will combine with `pow` so the substitution
        is valid, otherwise bool will be False.

        For noncommutative objects, `pow` will be an integer, and a factor
        `Pow(old.base, remainder_pow)` needs to be included. If there is
        no such factor, None is returned. For commutative objects,
        remainder_pow is always None.

        cti are the coefficient and terms of an exponent of self or old
        In this _eval_subs routine a change like (b**(2*x)).subs(b**x, y)
        will give y**2 since (b**x)**2 == b**(2*x); if that equality does
        not hold then the substitution should not occur so `bool` will be
        False.

        """
        coeff1, terms1 = ct1
        coeff2, terms2 = ct2
        if terms1 == terms2:
            if old.is_commutative:
                # Allow fractional powers for commutative objects
                pow = coeff1/coeff2
                try:
                    as_int(pow, strict=False)
                    combines = True
                except ValueError:
    >>> exp(-x).as_numer_denom()
    (1, exp(x))
    >>> exp(x).as_numer_denom()
    (exp(x), 1)
    """
    # this should be the same as Pow.as_numer_denom wrt
    # exponent handling
    exp = self.exp
    neg_exp = exp.is_negative
    if not neg_exp and not (-exp).is_negative:
        neg_exp = _coeff_isneg(exp)
    if neg_exp:
        return S.One, self.func(-exp)
    return self, S.One

@property
def exp(self):
    """
    Returns the exponent of the function.
    """
    return self.args[0]

def as_base_exp(self):
    """
    Returns the 2-tuple (base, exponent).
    """
    return self.func(1), Mul(*self.args)

def _eval_adjoint(self):
    return self.func(self.exp.adjoint())

def _eval_conjugate(self):
    return self.func(self.exp.conjugate())

def _eval_transpose(self):
    return self.func(self.exp.transpose())

def _eval_is_finite(self):
    arg = self.exp
    if arg.is_infinite:
        if arg.is_extended_negative:
            return True
        if arg.is_extended_positive:
            return False
    if arg.is_finite:
        return True

def _eval_is_rational(self):
    s = self.func(*self.args)
    if s.func == self.func:
        z = s.exp.is_zero
        if z:
            return True
        elif s.exp.is_rational and fuzzy_not(z):
            return False
    else:
        return s.is_rational

def _eval_is_zero(self):
    return self.exp is S.NegativeInfinity

def _eval_power(self, other):
    """exp(arg)**e -> exp(arg*e) if assumptions allow it.
    """
    b, e = self.as_base_exp()
    return Pow._eval_power(Pow(b, e, evaluate=False), other)

def _eval_expand_power_exp(self, **hints):
    from sympy import Sum, Product
    arg = self.args[0]
    if arg.is_Add and arg.is_commutative:
        return Mul.fromiter(self.func(x) for x in arg.args)
    elif isinstance(arg, Sum) and arg.is_commutative:
        return Product(self.func(arg.function), *arg.limits)
    return self.func(arg)
